css:
.proof-of-registration {
	font-size: 11pt;
	line-height: 1.5;
}

.proof-title {
	text-align: center;
	font-size: 16pt;
	font-weight: bold;
	margin: 0 0 24px;
}

.proof-date {
	text-align: right;
	margin: 0 0 22px;
}

.proof-identity {
	border: none;
	margin: 0 0 28px;
}
.proof-identity td {
	border: none;
	padding: 0 6px 2px 0;
	vertical-align: top;
}
.proof-identity td.label {
	width: 90px;
}

.proof-lead {
	margin: 0 0 18px;
}

.proof-qualification {
	margin: 0 0 18px;
}

.proof-modules {
	width: 100%;
	border-collapse: collapse;
	margin: 0 0 22px;
}
.proof-modules th,
.proof-modules td {
	border: none;
	text-align: left;
	padding: 1px 0;
	font-weight: normal;
}
.proof-modules th {
	padding-bottom: 8px;
	font-weight: bold;
}
/* Fixed rather than proportional, so the names line up in a column the way the
   typed original does. */
.proof-modules .module-code {
	width: 180px;
}

.proof-period {
	margin: 0 0 16px;
}

.proof-acknowledgement {
	margin: 0 0 12px;
}

/* Each block is the drawn mark sitting directly on the rule, so the signature
   reads as signed rather than as an image pasted near a line. */
.proof-signature {
	margin-top: 26px;
	page-break-inside: avoid;
}
.proof-signature .signature-image {
	display: block;
	height: 52px;
	width: auto;
	max-width: 260px;
	margin-bottom: -6px;
}
.proof-signature .signature-space {
	height: 46px;
}
.proof-signature .signature-rule {
	border-top: 1px solid #000;
	width: 240px;
}
.proof-signature .signature-label {
	font-weight: bold;
	padding-top: 2px;
}
